// src/app/api/admin/invoices/[id]/lines/route.ts
//
// POST — add a line to a DRAFT invoice: { title, description?, quantity, unit_price } (decimal strings). The invoice id comes from the
// URL; the amount of the line is GENERATED by the database (round(quantity x unit price, 2)) and the invoice total is re-derived by
// its guard trigger, so nothing monetary is computed or trusted here. An issued invoice's lines cannot change: the database
// refuses the insert (55000), reported as 409.

import { NextResponse } from 'next/server'
import { requireActiveAdmin, queryFailure, ADMIN_UUID_RE } from '@/lib/admin-api-auth'
import { parseInvoiceLine } from '@/lib/commerce/draft-input'

export const dynamic = 'force-dynamic'

export async function POST(request: Request, { params }: { params: { id: string } }) {
  const auth = await requireActiveAdmin()
  if (!auth.ok) return auth.response
  const id = typeof params?.id === 'string' ? params.id.trim() : ''
  if (!ADMIN_UUID_RE.test(id)) return NextResponse.json({ error: 'Not found' }, { status: 404 })
  try {
    const parsed = parseInvoiceLine(await request.json().catch(() => null), false)
    if (!parsed.ok) return NextResponse.json({ error: parsed.error }, { status: 400 })

    const { data: inv } = await auth.db.from('project_invoices').select('id, status').eq('id', id).maybeSingle()
    if (!inv) return NextResponse.json({ error: 'Not found' }, { status: 404 })
    if (inv.status !== 'draft') return NextResponse.json({ error: 'Only a draft invoice can be changed.', code: 'not_draft' }, { status: 409 })

    const { data: last } = await auth.db.from('invoice_line_items').select('sort_order').eq('invoice_id', id).order('sort_order', { ascending: false }).limit(1).maybeSingle()
    const { data, error } = await auth.db
      .from('invoice_line_items')
      .insert({ invoice_id: id, sort_order: (Number(last?.sort_order) || 0) + 1, title: parsed.line.title, description: parsed.line.description || null, quantity: parsed.line.quantity, unit_price: parsed.line.unit_price })
      .select('id, title, description, quantity, unit_price, line_amount, sort_order')
      .single()
    if (error) {
      const code = (error as { code?: string }).code
      if (code === '55000') return NextResponse.json({ error: 'Only a draft invoice can be changed.', code: 'not_draft' }, { status: 409 })
      return queryFailure('invoice line insert', error)
    }
    return NextResponse.json({ line: data }, { status: 201 })
  } catch (error) {
    return queryFailure('invoice line insert', error)
  }
}
